/**
 * JavaScript otimizado para a página de relatório
 * Performance otimizada com lazy loading e virtual scrolling
 */

// Cache de elementos DOM
const DOM_CACHE = new Map();

// Configurações de performance
const PERF_CONFIG = {
  SEARCH_DEBOUNCE: 300,
  PAGINATION_SIZE: 50,
  LAZY_LOAD_THRESHOLD: 0.1,
};

/**
 * Cache otimizado para elementos DOM
 */
function getCachedElement(selector) {
  if (!DOM_CACHE.has(selector)) {
    DOM_CACHE.set(selector, document.querySelector(selector));
  }
  return DOM_CACHE.get(selector);
}

/**
 * Inicialização otimizada da página de relatório
 */
function initRelatorioPage() {
  console.log("🚀 Inicializando página de relatório otimizada");

  // Usar requestIdleCallback para inicialização não crítica
  if ("requestIdleCallback" in window) {
    requestIdleCallback(() => {
      console.log("⏱️ Executando inicialização via requestIdleCallback");
      setupTableOptimizations();
      setupSearchOptimizations();
      setupImageModalOptimizations();
      setupPaginationOptimizations();
      console.log("✅ Inicialização completa");
    });
  } else {
    setTimeout(() => {
      console.log("⏱️ Executando inicialização via setTimeout");
      setupTableOptimizations();
      setupSearchOptimizations();
      setupImageModalOptimizations();
      setupPaginationOptimizations();
      console.log("✅ Inicialização completa");
    }, 100);
  }
}

/**
 * Otimizações de tabela.
 *
 * As linhas NUNCA saem do DOM: a paginação e a busca ESCONDEM (display:none)
 * e a ordenação reordena os mesmos elementos. Antes o virtual scroll trocava
 * as linhas por clones, o que matava os listeners dos botões (Editar/Excluir
 * no Editar Dados) e escondia checkboxes da reanálise seletiva.
 */
function setupTableOptimizations() {
  document.querySelectorAll("table").forEach((table) => {
    if (!table.querySelector("tbody")) return;
    table._todasAsLinhas = Array.from(table.querySelectorAll("tbody tr"));
    setupTableSorting(table);
    // Lazy loading para células com imagens
    enableLazyImageLoading(table);
  });
}

/** Linhas "de dados" da tabela (cache do setup ou consulta ao DOM). */
function tabelaLinhas(table) {
  return table._todasAsLinhas || Array.from(table.querySelectorAll("tbody tr"));
}

/**
 * Ordenação por clique no cabeçalho (th.sortable[data-column]).
 */
function setupTableSorting(table) {
  const headers = table.querySelectorAll("th.sortable[data-column]");
  if (!headers.length) return;

  headers.forEach((th) => {
    th.style.cursor = "pointer";
    th.setAttribute("title", "Clique para ordenar");
    th.addEventListener("click", () => ordenarTabela(table, th));
  });
}

function ordenarTabela(table, th) {
  const coluna = parseInt(th.dataset.column, 10);
  if (!Number.isFinite(coluna)) return;
  const tbody = table.querySelector("tbody");
  const linhas = tabelaLinhas(table);
  const direcao = th.dataset.direcao === "asc" ? "desc" : "asc";

  table.querySelectorAll("th.sortable").forEach((outro) => {
    outro.removeAttribute("data-direcao");
    const iconeOutro = outro.querySelector(".sort-icon");
    if (iconeOutro) iconeOutro.className = "bi bi-chevron-expand ms-1 sort-icon";
  });
  th.dataset.direcao = direcao;
  const icone = th.querySelector(".sort-icon");
  if (icone) {
    icone.className =
      direcao === "asc"
        ? "bi bi-chevron-up ms-1 sort-icon"
        : "bi bi-chevron-down ms-1 sort-icon";
  }

  const fator = direcao === "asc" ? 1 : -1;
  const valorTexto = (tr) => (tr.cells[coluna] ? tr.cells[coluna].textContent.trim() : "");
  const valorNumero = (texto) => {
    const numero = parseFloat(texto.replace(/\./g, "").replace(",", "."));
    return Number.isFinite(numero) ? numero : null;
  };

  linhas.sort((a, b) => {
    const textoA = valorTexto(a);
    const textoB = valorTexto(b);
    const numeroA = valorNumero(textoA);
    const numeroB = valorNumero(textoB);
    if (numeroA !== null && numeroB !== null) return (numeroA - numeroB) * fator;
    return textoA.localeCompare(textoB, "pt-BR", { sensitivity: "base" }) * fator;
  });

  // Reordena os MESMOS nós (não recria) e reaplica busca/paginação atuais.
  linhas.forEach((tr) => tbody.appendChild(tr));

  if (table._buscaTexto) {
    aplicarBusca(table, table._buscaTexto);
  } else if (table._paginacao) {
    table._paginacao.aplicar();
  }
}

/**
 * Lazy loading para imagens em células
 */
function enableLazyImageLoading(table) {
  const imageButtons = table.querySelectorAll(".view-image-btn");

  if ("IntersectionObserver" in window) {
    const imageObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const button = entry.target;
            // Pré-carregar a imagem quando o botão fica visível
            const imageUrl = button.dataset.image;
            if (imageUrl) {
              const img = new Image();
              img.src = imageUrl;
            }
            imageObserver.unobserve(button);
          }
        });
      },
      { threshold: PERF_CONFIG.LAZY_LOAD_THRESHOLD }
    );

    imageButtons.forEach((button) => imageObserver.observe(button));
  }
}

/**
 * Otimizações de busca com debounce
 */
function setupSearchOptimizations() {
  const searchInputs = document.querySelectorAll(".search-input");

  searchInputs.forEach((input) => {
    const tableId = input.dataset.table;
    const table = document.getElementById(tableId);

    if (!table) return;

    const optimizedSearch = debounce((searchTerm) => {
      aplicarBusca(table, searchTerm);
    }, PERF_CONFIG.SEARCH_DEBOUNCE);

    input.addEventListener("input", (e) => optimizedSearch(e.target.value));
  });
}

/**
 * Aplica a busca: esconde as linhas que não casam, destaca as que casam e
 * respeita a paginação (quando existir). As linhas continuam no DOM.
 */
function aplicarBusca(table, searchTerm) {
  const termo = (searchTerm || "").trim().toLowerCase();
  const linhas = tabelaLinhas(table);
  table._buscaTexto = termo;

  // Sempre limpa destaques antigos: antes eles ficavam "grudados" nas linhas
  // e buscas repetidas aninhavam <mark> uns dentro dos outros.
  linhas.forEach(limparDestaques);

  if (!termo) {
    if (table._paginacao) table._paginacao.setFiltro(linhas);
    else linhas.forEach((tr) => (tr.style.display = ""));
    return;
  }

  const encontradas = [];
  linhas.forEach((tr) => {
    if (tr.textContent.toLowerCase().includes(termo)) {
      highlightSearchTerm(tr, searchTerm);
      encontradas.push(tr);
    }
  });

  if (table._paginacao) {
    table._paginacao.setFiltro(encontradas);
  } else {
    const visiveis = new Set(encontradas);
    linhas.forEach((tr) => {
      tr.style.display = visiveis.has(tr) ? "" : "none";
    });
  }
}

/**
 * Destaca o termo de busca criando elementos <mark> (sem innerHTML).
 *
 * Cria os nós diretamente (textContent) em vez de montar HTML: não há
 * injeção possível com dados do banco e o destaque pode ser desfeito depois
 * (ver limparDestaques) sem sobrar spans vazios.
 */
function highlightSearchTerm(row, searchTerm) {
  if (!searchTerm.trim()) return;

  const termo = searchTerm.toLowerCase();
  const walker = document.createTreeWalker(
    row,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );

  const textNodes = [];
  let node;

  while ((node = walker.nextNode())) {
    textNodes.push(node);
  }

  textNodes.forEach((textNode) => {
    const text = textNode.textContent;
    if (!text.toLowerCase().includes(termo)) return;

    const regex = new RegExp(`(${escapeRegex(searchTerm)})`, "gi");
    const partes = text.split(regex);
    if (partes.length <= 1) return;

    const fragment = document.createDocumentFragment();
    partes.forEach((parte) => {
      if (!parte) return;
      if (parte.toLowerCase() === termo) {
        const mark = document.createElement("mark");
        mark.className = "search-highlight";
        mark.textContent = parte;
        fragment.appendChild(mark);
      } else {
        fragment.appendChild(document.createTextNode(parte));
      }
    });
    textNode.parentNode.replaceChild(fragment, textNode);
  });
}

/** Desfaz os destaques de busca de uma linha (inclusive de buscas antigas). */
function limparDestaques(row) {
  row.querySelectorAll("mark.search-highlight").forEach((mark) => {
    mark.replaceWith(document.createTextNode(mark.textContent));
  });
  row.normalize();
}

/**
 * Escape regex para busca segura
 */
function escapeRegex(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Otimizações do modal de imagem.
 *
 * A abertura do modal (e o preenchimento da tabela de dados do item) é
 * responsabilidade de static/js/image-modal.js, compartilhado por todas as
 * telas com botão "Ver". Aqui fica só o pré-carregamento das imagens que
 * entram na viewport, que é otimização específica das tabelas grandes.
 */
function setupImageModalOptimizations() {
  // (o pré-carregamento é feito por enableLazyImageLoading)
}

/**
 * Modal de imagem otimizado com lazy loading
 */
function openOptimizedImageModal(imageUrl) {
  console.log("🖼️ Abrindo modal otimizado para:", imageUrl);

  // Usar modal existente do template
  const modal = document.getElementById("imageModal");

  if (!modal) {
    console.error("❌ Modal de imagem não encontrado no DOM");
    return;
  }

  console.log("✅ Modal encontrado:", modal);

  const modalImg = modal.querySelector("#modalImage");
  const loadingDiv = modal.querySelector("#imageLoading");
  const errorDiv = modal.querySelector("#imageLoadError");
  const filenameSpan = modal.querySelector("#imageModalFilename");
  const downloadBtn = modal.querySelector("#downloadImageBtn");

  console.log("🔍 Elementos do modal:", {
    modalImg: !!modalImg,
    loadingDiv: !!loadingDiv,
    errorDiv: !!errorDiv,
    filenameSpan: !!filenameSpan,
    downloadBtn: !!downloadBtn,
  });

  // Reset do estado
  modalImg.style.display = "none";
  if (loadingDiv) loadingDiv.classList.remove("d-none");
  if (errorDiv) errorDiv.classList.add("d-none");

  // Extrair nome do arquivo da URL
  const filename = imageUrl.split("/").pop() || "imagem";
  if (filenameSpan) filenameSpan.textContent = filename;

  // Configurar download
  if (downloadBtn) {
    downloadBtn.href = imageUrl;
    downloadBtn.download = filename;
  }

  // Lazy load da imagem
  const img = new Image();

  img.onload = function () {
    console.log("✅ Imagem carregada com sucesso");
    modalImg.src = this.src;
    modalImg.style.display = "block";
    if (loadingDiv) loadingDiv.classList.add("d-none");
  };

  img.onerror = function () {
    console.error("❌ Erro ao carregar imagem:", imageUrl);
    if (loadingDiv) loadingDiv.classList.add("d-none");
    if (errorDiv) errorDiv.classList.remove("d-none");
    console.error("Erro ao carregar imagem:", imageUrl);
  };

  img.src = imageUrl;

  // Mostrar modal
  if (typeof bootstrap !== "undefined") {
    console.log("🚀 Mostrando modal com Bootstrap");
    const bsModal = new bootstrap.Modal(modal);
    bsModal.show();
  } else {
    console.error("❌ Bootstrap não está disponível");
  }
}

/**
 * Otimizações de paginação
 */
function setupPaginationOptimizations() {
  document.querySelectorAll("table").forEach((table) => {
    if (tabelaLinhas(table).length > PERF_CONFIG.PAGINATION_SIZE) {
      enablePagination(table);
    }
  });
}

/**
 * Localiza o <ul class="pagination"> da tabela.
 *
 * O id segue o padrão da tabela (`<aba>-table` -> `<aba>-pagination`); o
 * fallback cobre telas fora do padrão. Antes a busca partia de
 * `table.parentNode` (o .table-responsive) e o <nav> da paginação era IRMÃO
 * dele — nunca encontrava e a paginação nunca ligava.
 */
function localizarPaginacao(table) {
  const porId = table.id
    ? document.getElementById(table.id.replace(/-table$/, "-pagination"))
    : null;
  if (porId) return porId;

  const container = table.closest(".table-responsive") || table.parentNode;
  return container && container.parentNode
    ? container.parentNode.querySelector(".pagination")
    : null;
}

/** Redesenha os controles da paginação (janela de páginas + avançar/voltar). */
function atualizarPaginacao(ul, pagina, totalPaginas) {
  ul.innerHTML = "";
  if (totalPaginas <= 1) return;

  const item = (rotulo, destino, ativo, desabilitado) => {
    const li = document.createElement("li");
    li.className =
      "page-item" + (ativo ? " active" : "") + (desabilitado ? " disabled" : "");
    const link = document.createElement("a");
    link.className = "page-link";
    link.href = "#";
    link.dataset.page = destino;
    link.textContent = rotulo;
    li.appendChild(link);
    return li;
  };

  ul.appendChild(item("«", Math.max(1, pagina - 1), false, pagina === 1));
  const inicio = Math.max(1, pagina - 2);
  const fim = Math.min(totalPaginas, inicio + 4);
  for (let p = inicio; p <= fim; p++) {
    ul.appendChild(item(String(p), p, p === pagina, false));
  }
  ul.appendChild(item("»", Math.min(totalPaginas, pagina + 1), false, pagina === totalPaginas));
}

/**
 * Paginação que ESCONDE as linhas fora da página (display:none) em vez de
 * removê-las do DOM: checkboxes da reanálise e listeners continuam válidos em
 * todas as páginas (inclusive nas escondidas).
 */
function enablePagination(table) {
  const todas = tabelaLinhas(table);
  const pageSize = PERF_CONFIG.PAGINATION_SIZE;
  const pagination = localizarPaginacao(table);
  if (!pagination) return;

  const state = { filtradas: todas, pagina: 1, totalPaginas: 1 };

  function render() {
    state.totalPaginas = Math.max(1, Math.ceil(state.filtradas.length / pageSize));
    if (state.pagina > state.totalPaginas) state.pagina = state.totalPaginas;
    const inicio = (state.pagina - 1) * pageSize;
    const fim = inicio + pageSize;
    todas.forEach((tr) => (tr.style.display = "none"));
    state.filtradas.slice(inicio, fim).forEach((tr) => (tr.style.display = ""));
    atualizarPaginacao(pagination, state.pagina, state.totalPaginas);
  }

  table._paginacao = {
    paginaAtual: () => state.pagina,
    setFiltro(lista) {
      state.filtradas = lista;
      state.pagina = 1;
      render();
    },
    aplicar() {
      render();
    },
  };

  pagination.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-page]");
    if (!btn) return;
    e.preventDefault();
    const pagina = parseInt(btn.dataset.page, 10);
    if (
      Number.isFinite(pagina) &&
      pagina >= 1 &&
      pagina <= state.totalPaginas &&
      pagina !== state.pagina
    ) {
      state.pagina = pagina;
      render();
    }
  });

  render();
}

/**
 * Throttle function para performance
 */
function throttle(func, limit) {
  let inThrottle;
  return function () {
    if (!inThrottle) {
      func.apply(this, arguments);
      inThrottle = true;
      setTimeout(() => (inThrottle = false), limit);
    }
  };
}

/**
 * Debounce function para performance
 */
function debounce(func, wait) {
  let timeout;
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func.apply(this, args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

// Inicializar quando DOM estiver pronto
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initRelatorioPage);
} else {
  initRelatorioPage();
}

// Exportar funções para uso global
window.RelatorioOptimizado = {
  initRelatorioPage,
  getCachedElement,
  throttle,
  debounce,
};
